:root {
  --bg-wristband: #1a1033;
  --bg-header: #f7c948;
  --bg-footer: #2d1f5e;
  --accent-orange: #ff7a1a;
  --accent-amber: #f7c948;
  --text-dark: #1a1033;
  --text-light: #f0eaff;
  --text-muted: #a99dcc;
  --text-label: #7b6da8;
  --border-glow: #7c3aed;
  --bar-color: #f0eaff;
  --perk-bg: #3d2c7a;
  --badge-bg: #ff7a1a;
  --badge-text: #ffffff;
}

.wristband {
  width: 480px;
  background-color: var(--bg-wristband);
  border-radius: 16px;
  border: 2px solid var(--border-glow);
  overflow: hidden;
  margin: 0 auto;
}

.wristband-header {
  background-color: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
}

.event-icon {
  font-size: 32px;
  line-height: 1;
}

.event-info {
  flex: 1;
}

.event-title {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-dark);
  margin: 0;
  line-height: 1.1;
  letter-spacing: -0.3px;
}

.event-date {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-dark);
  margin: 2px 0 0 0;
  opacity: 0.75;
}

.wristband-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.5px;
  padding: 4px 10px;
  border-radius: 20px;
  text-transform: uppercase;
}

.wristband-body {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 16px;
}

.attendee-block {
  flex: 0 0 140px;
}

.label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--text-label);
  margin: 0 0 2px 0;
}

.attendee-name {
  font-size: 17px;
  font-weight: 800;
  color: var(--text-light);
  margin: 0 0 2px 0;
}

.attendee-id {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
  margin: 0;
}

.divider-dots {
  width: 2px;
  height: 60px;
  background: repeating-linear-gradient(
    to bottom,
    var(--border-glow) 0px,
    var(--border-glow) 4px,
    transparent 4px,
    transparent 8px
  );
  margin: 0 16px;
  flex-shrink: 0;
}

.details-grid {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 16px;
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.detail-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--accent-amber);
  margin: 0;
}

.wristband-footer {
  background-color: var(--bg-footer);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.barcode {
  display: flex;
  align-items: stretch;
  height: 36px;
  gap: 2px;
}

.bar {
  width: 3px;
  background-color: var(--bar-color);
  border-radius: 1px;
}

.bar.thin {
  width: 1.5px;
  opacity: 0.6;
}

.bar.wide {
  width: 5px;
}

.perks {
  display: flex;
  gap: 8px;
}

.perk {
  background-color: var(--perk-bg);
  color: var(--text-light);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
  border: 1px solid var(--border-glow);
}
